{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "In healthy men, 11C-SCH 23390, the direct phenyl analog of the query core, showed rapid transfer into the brain with 1.2% of injected radioactivity present in the brain at 4.5 min, demonstrating robust CNS access for this benzazepine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The 4-iodophenyl analog of the query showed good rat brain uptake after IV injection (2.27% dose/whole brain at 2 min), directly supporting CNS penetration for halogenated 1-aryl benzazepines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The 3-iodophenyl analog showed good initial brain uptake in rats (1.59% dose/organ at 2 min), confirming that larger halogen substituents on the 1-aryl ring do not abolish BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The des-chloro analog [123I]SCH 23982 had a brain-to-blood ratio of about 1.2 in rats, indicating active brain uptake and supporting meaningful CNS exposure for the benzazepine chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analog of SCH 23390 and its halogenated 1-aryl benzazepine congeners, which show rapid and substantial brain uptake in human PET and rat biodistribution studies; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or unbound brain concentration measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query; however, close analogs show net brain uptake sufficient for CNS access.",
    "The added bromo-dihydrobenzofuran moiety is not directly represented in the evidence set, though it increases lipophilicity and is unlikely to abolish the conserved CNS-penetrant phenotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

